import { toModelEntry } from 'jsr:@skmtc/core@0.28.3'
import { ZodProjection } from "./ZodProjection.ts";
import { toEnrichmentSchema, type EnrichmentSchema } from "./enrichments.ts";
import denoJson from "../deno.json" with { type: "json" };

export const zodEntry = toModelEntry<EnrichmentSchema>({
  id: denoJson.name,
  toEnrichmentSchema,
  transform({ context, refName }) {
    context.insertModel(ZodProjection, refName);
  },
});

===== src/base.ts =====
import { camelCase, decapitalize } from 'jsr:@skmtc/core@0.28.3'
import { toTsModelProjectionBase } from 'jsr:@skmtc/lang-typescript@0.12.17'
import { join } from "jsr:@std/path@^1.1.2";
import { toEnrichmentSchema, type EnrichmentSchema } from "./enrichments.ts";
import denoJson from "../deno.json" with { type: "json" };

export const ZodBase = toTsModelProjectionBase<EnrichmentSchema>({
  id: denoJson.name,

  toIdentifierName({ refName }): string {
    return decapitalize(camelCase(refName));
  },

  toIdentifierType: () => ({ type: "variable" }),

  toExportPath({ refName, enrichments, variant }): string {
    const name = this.toIdentifierName({ refName, enrichments, variant });

    return join("@", "types", `${decapitalize(name)}.generated.ts`);
  },

  toEnrichmentSchema,
});

===== src/Zod.ts =====
import { ZodString } from "./ZodString.ts";
import { ZodArray } from "./ZodArray.ts";
import { ZodRef } from "./ZodRef.ts";
import { ZodObject } from "./ZodObject.ts";
import { ZodUnion } from "./ZodUnion.ts";
import type { Modifiers, SchemaToValueFn, SchemaType } from 'jsr:@skmtc/core@0.28.3'
import { ZodNumber } from "./ZodNumber.ts";
import { ZodInteger } from "./ZodInteger.ts";
import { ZodBoolean } from "./ZodBoolean.ts";
import { ZodVoid } from "./ZodVoid.ts";
import { ZodUnknown } from "./ZodUnknown.ts";
import { toGeneratorOnlyKey, toRefName } from 'jsr:@skmtc/core@0.28.3'
import { zodEntry } from "./mod.ts";

/**
 * Maps a parsed schema node to its Zod snippet. Fine-grained attribution
 * is captured via each snippet's super call, which snapshots the schema's
 * `stackTrail` (`stackTrail: schema.stackTrail.clone()`) — no
 * router-level wrapper. The originating node is passed to every snippet,
 * including the ones that otherwise receive only decomposed parts
 * (`items` / `members` / `refName`) or nothing (`void` / `unknown`).
 */
export const toZodValue: SchemaToValueFn = ({
  schema: schemaNode,
  destinationPath,
  required,
  context,
  rootRef,
}) => {
  // `schemaNode` arrives typed as the generic `Schema` parameter, and TypeScript
  // does not narrow a type parameter by discriminant. Widening it to the
  // `SchemaType` union lets the switch below narrow each case on its own —
  // generator code narrows, it does not assert.
  const schema: SchemaType = schemaNode;

  const modifiers: Modifiers = {
    required,
    // description: 'description' in schema ? schema.description : undefined,
    nullable: "nullable" in schema ? schema.nullable : undefined,
  };

  const generatorKey = toGeneratorOnlyKey({ generatorId: zodEntry.id });

  switch (schema.type) {
    case "custom":
      return schema;
    case "ref":
      return new ZodRef({
        context,
        destinationPath,
        refName: toRefName(schema.$ref),
        modifiers,
        rootRef,
        schema,
      });
    case "array":
      return new ZodArray({
        context,
        destinationPath,
        modifiers,
        items: schema.items,
        generatorKey,
        rootRef,
        schema,
      });
    case "object":
      return new ZodObject({
        context,
        destinationPath,
        objectSchema: schema,
        modifiers,
        generatorKey,
        rootRef,
      });
    case "union":
      return new ZodUnion({
        context,
        destinationPath,
        members: schema.members,
        discriminator: schema.discriminator,
        modifiers,
        generatorKey,
        rootRef,
        schema,
      });
    case "number":
      return new ZodNumber({
        context,
        modifiers,
        schema,
        destinationPath,
        generatorKey,
      });
    case "integer":
      return new ZodInteger({
        context,
        schema,
        modifiers,
        destinationPath,
        generatorKey,
      });
    case "boolean":
      return new ZodBoolean({
        context,
        modifiers,
        schema,
        destinationPath,
        generatorKey,
      });
    case "void":
      return new ZodVoid({ context, destinationPath, generatorKey });
    case "string":
      return new ZodString({
        context,
        stringSchema: schema,
        modifiers,
        destinationPath,
        generatorKey,
      });
    case "unknown":
      return new ZodUnknown({ context, destinationPath, generatorKey, schema });
    default: {
      // Exhaustiveness check - if SchemaType is properly defined, this should never happen
      const _exhaustive: never = schema;
      throw new Error(`Unhandled schema type: ${_exhaustive}`);
    }
  }
};

===== src/ZodProjection.ts =====
import { camelCase, capitalize, type ContentSettings, type GenerateContextType, type RefName, type TypeSystemValue } from 'jsr:@skmtc/core@0.28.3'
import { createVariable } from 'jsr:@skmtc/lang-typescript@0.12.17'
import { toZodValue } from "./Zod.ts";
import { ZodBase } from "./base.ts";
import type { EnrichmentSchema } from "./enrichments.ts";

type ConstructorArgs = {
  context: GenerateContextType;
  destinationPath: string;
  refName: RefName;
  settings: ContentSettings<EnrichmentSchema>;
  rootRef?: RefName;
};

export class ZodProjection extends ZodBase {
  value: TypeSystemValue;
  constructor(
    { context, refName, settings, destinationPath, rootRef }: ConstructorArgs,
  ) {
    super({ context, refName, settings });

    const schema = context.resolveSchemaRefOnce(refName, ZodBase.id);

    this.value = toZodValue({
      schema,
      required: true,
      destinationPath,
      context,
      rootRef,
    });

    // A recursive schema renders a `z.lazy(() => self)` back-reference
    // (see ZodRef). The enclosing `export const` then references its own
    // initializer, which TypeScript cannot type by inference — TS7022 /
    // TS7024. Annotating the identifier with `typeName` makes `Definition`
    // emit `export const x: z.ZodType<X> = ...`, breaking the cycle.
    //
    // Detected via `modelDepth`, not by rendering: `resolveSchemaRefOnce`
    // above set this key to 1, and every terminal back-reference to this
    // model bumps it further (see ZodRef), so `> 1` means a recursive cycle
    // was emitted into this model's value. (Reading the rendered string here
    // would pre-render the value tree outside the attribution pass and orphan
    // every inner snippet from the gen-map.) Self-recursion is what OpenAPI
    // schemas produce; mutual recursion is not detected by this check.
    if (context.modelDepth[`${ZodBase.id}:${refName}`] > 1) {
      this.settings.identifier.typeName = `z.ZodType<${
        capitalize(camelCase(refName))
      }>`;
    }
  }

  static schemaToValueFn = (...args: Parameters<typeof toZodValue>) => {
    return toZodValue(...args);
  };

  static createIdentifier = createVariable;

  override toString() {
    return `${this.value}`;
  }
}

